== resources/officefloor/rest/api/sheets/{sheetId}/people/{personId}/retire.PUT.yml
# PUT /api/sheets/{sheetId}/people/{personId}/retire — retire the person from a date.
# Body: { "date": "YYYY-MM-DD" } (blank = the sheet's today).
guard:
  class: net.officefloor.hq.app.role.GuardViewer
  next: archived
archived:
  class: net.officefloor.hq.app.sheet.GuardArchived
  next: validate
validate:
  class: net.officefloor.hq.app.person.ValidateRetire
