        findByPersonIdOrderByIdAsc(personId).stream().filter(b -> !b.getMadeOn().isAfter(date))
                .reduce((a, b) -> b)
                .ifPresent(last -> last.getBound().forEach(c -> bound.put(c.getClaimId(), c.getStatedDue())));
        return bound;
    }
